import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Slot } from "radix-ui";

import { Separator } from "./separator";

import { useDescendantFlags } from "../lib/descendant-flags";
import { useInFrame } from "../lib/frame-context";
import { cn } from "../lib/utils";
import { Icon, type IconSource } from "./icon";
import { Tooltip } from "./tooltip";

import controlStyles from "./controls.module.css";
import helperStyles from "./helpers.module.css";
import itemStyles from "./item.module.css";

const ItemGroupContext = React.createContext(false);

const groupFlags = { "data-has-sm": '[data-size="sm"]', "data-has-xs": '[data-size="xs"]' };
const groupWatch = { attributes: ["data-size"] };
const itemFlags = { "data-has-description": '[data-slot="item-description"]' };

function ItemGroup({ className, ref, ...props }: React.ComponentProps<"div">) {
  const groupRef = useDescendantFlags(groupFlags, groupWatch, ref);
  return (
    <ItemGroupContext value>
      <div
        ref={groupRef}
        role="list"
        data-slot="item-group"
        className={cn(
          "group/item-group flex w-full flex-col gap-4 data-[has-sm]:gap-2.5 data-[has-xs]:gap-2",
          className
        )}
        {...props}
      />
    </ItemGroupContext>
  );
}
ItemGroup.displayName = "ItemGroup";

function ItemSeparator({ className, ref, ...props }: React.ComponentProps<typeof Separator>) {
  return (
    <Separator
      ref={ref}
      data-slot="item-separator"
      orientation="horizontal"
      className={cn("my-2", className)}
      {...props}
    />
  );
}
ItemSeparator.displayName = "ItemSeparator";

const itemVariants = cva(
  [
    controlStyles.focusOutline,
    "group/item flex w-full flex-wrap rounded-lg text-sm transition-colors duration-(--cipher-duration-fast) [a]:transition-colors [a]:hover:bg-[color:var(--cipher-action-ghost-hover)]"
  ],
  {
    variants: {
      variant: {
        default: "border border-transparent",
        outline: "border border-[color:var(--cipher-line-soft)]",
        muted: "border border-transparent bg-muted/50"
      },
      size: {
        default: "gap-2.5 px-3 py-2.5",
        md: "gap-2.5 px-3 py-2.5",
        sm: "gap-2.5 px-3 py-2.5",
        xs: "gap-2 px-3 py-2 in-data-[slot=dropdown-menu-content]:p-0"
      }
    },
    defaultVariants: {
      variant: "default",
      size: "default"
    }
  }
);

export type ItemProps = Omit<React.ComponentPropsWithoutRef<"div">, "title"> &
  VariantProps<typeof itemVariants> & {
    asChild?: boolean;
    title?: React.ReactNode;
    description?: React.ReactNode;
    icon?: IconSource;
    media?: React.ReactNode;
    badge?: React.ReactNode;
    meta?: React.ReactNode;
    error?: React.ReactNode;
    actions?: React.ReactNode;
    actionsPlacement?: "end" | "below";
    unread?: boolean;
    resolved?: boolean;
    /**
     * Keeps the title and description on one line with an ellipsis, and puts the full text in a
     * native tooltip. Defaults to true, except on a row with actions at the default or md size,
     * where the title wraps beside its timestamp. titleLines takes over the title when set, so
     * truncate then governs only the description.
     */
    truncate?: boolean;
    /**
     * Clamps the title to this many lines and shows the full title in a Tooltip while it is cut
     * off. Unset leaves the title to truncate. titleLines={1} reads like truncate but uses a Cipher
     * tooltip instead of a native one.
     */
    titleLines?: number;
    mono?: boolean;
  };

function ClampedTitle({
  lines,
  className,
  children
}: {
  lines: number;
  className?: string;
  children: React.ReactNode;
}) {
  const [element, setElement] = React.useState<HTMLSpanElement | null>(null);
  const [clamped, setClamped] = React.useState(false);
  React.useLayoutEffect(() => {
    if (!element) return;
    const measure = () => setClamped(element.scrollHeight > element.clientHeight + 1);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [element, lines, children]);
  return (
    <Tooltip content={clamped ? children : undefined}>
      <span ref={setElement} className={className} style={{ WebkitLineClamp: lines }}>
        {children}
      </span>
    </Tooltip>
  );
}
const hasVisibleText = (root: HTMLElement) => {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    if (!node.textContent?.trim()) continue;
    let element = node.parentElement;
    while (element && element !== root && element.offsetWidth > 1) element = element.parentElement;
    if (element === root) return true;
  }
  return false;
};

function useIconOnly(enabled: boolean) {
  const [element, setElement] = React.useState<HTMLDivElement | null>(null);
  const [iconOnly, setIconOnly] = React.useState(false);
  React.useLayoutEffect(() => {
    if (!enabled || !element) return setIconOnly(false);
    const sync = () => setIconOnly(!hasVisibleText(element));
    sync();
    const observer = new MutationObserver(sync);
    observer.observe(element, { childList: true, subtree: true, characterData: true });
    return () => observer.disconnect();
  }, [enabled, element]);
  return [iconOnly, setElement] as const;
}

function Item({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  title,
  description,
  icon,
  media,
  badge,
  meta,
  error,
  actions,
  actionsPlacement = "end",
  unread,
  resolved,
  truncate,
  titleLines,
  mono = false,
  children,
  ref,
  ...props
}: ItemProps & { ref?: React.Ref<HTMLDivElement> }) {
  const inList = React.useContext(ItemGroupContext);
  const Comp = asChild ? Slot.Root : "div";
  const itemRef = useDescendantFlags<HTMLDivElement>(itemFlags, undefined, ref);
  const composed = title !== undefined || media || icon || description || actions;
  const hasActions = Boolean(actions) && (size === "default" || size === "md");
  const truncated = truncate ?? !hasActions;
  const [actionsIconOnly, actionsRef] = useIconOnly(hasActions);
  const metaNode = meta && (
    <span className={cn(itemStyles.meta, typeof meta === "string" && itemStyles.mono)}>
      {meta}
    </span>
  );
  const body = composed ? (
    <>
      {unread && <span className="sr-only">Unread</span>}
      {(media || icon) && (
        <span className={itemStyles.lead}>
          {media ?? <Media icon={icon} size={size === "sm" ? "sm" : "md"} />}
          {unread && <span className={itemStyles.unread} aria-hidden="true" />}
        </span>
      )}
      <div
        className={itemStyles.main}
        data-actions-below={
          (Boolean(actions || meta) && actionsPlacement === "below" && size !== "sm") || undefined
        }
        data-has-actions={hasActions || undefined}
        data-actions-icon-only={(hasActions && actionsIconOnly) || undefined}
      >
        <div className={itemStyles.copy}>
          <div className={itemStyles.titleLine}>
            {unread && !(media || icon) && (
              <span className={itemStyles.unread} aria-hidden="true" />
            )}
            {titleLines ? (
              <ClampedTitle
                lines={titleLines}
                className={cn(itemStyles.title, itemStyles.clamp, mono && itemStyles.mono)}
              >
                {title}
              </ClampedTitle>
            ) : (
              <span
                className={cn(itemStyles.title, mono && itemStyles.mono)}
                title={truncated && typeof title === "string" ? title : undefined}
              >
                {title}
              </span>
            )}
            {badge}
            {hasActions && metaNode}
          </div>
          {description && (
            <div
              className={itemStyles.description}
              title={truncated && typeof description === "string" ? description : undefined}
            >
              {description}
            </div>
          )}
          {error && (
            <div className={itemStyles.error}>
              <Icon name="alert" size={14} />
              {error}
            </div>
          )}
          {children && !asChild && <div className={itemStyles.body}>{children}</div>}
        </div>
        {(actions || meta) && (
          <div
            ref={actionsRef}
            className={cn(
              itemStyles.actions,
              actionsPlacement === "below" && size !== "sm" && itemStyles.below
            )}
          >
            {!hasActions && metaNode}
            {actions}
          </div>
        )}
      </div>
    </>
  ) : (
    children
  );
  const content =
    composed && asChild && React.isValidElement<{ children?: React.ReactNode }>(children)
      ? React.cloneElement(children, undefined, body)
      : body;
  const item = (
    <Comp
      ref={itemRef}
      role={inList && !asChild ? "listitem" : undefined}
      data-slot="item"
      data-variant={variant}
      data-size={size}
      data-unread={unread || undefined}
      data-resolved={resolved || undefined}
      data-has-actions={(composed && hasActions) || undefined}
      className={cn(
        itemVariants({ variant, size }),
        composed ? itemStyles.layout : "items-center",
        !truncated && itemStyles.wrap,
        className
      )}
      {...props}
    >
      {content}
    </Comp>
  );
  return inList && asChild ? <div role="listitem">{item}</div> : item;
}
Item.displayName = "Item";

const itemMediaVariants = cva(
  "flex shrink-0 items-center justify-center gap-2 group-data-[has-description]/item:translate-y-0.5 group-data-[has-description]/item:self-start [&_svg]:pointer-events-none",
  {
    variants: {
      variant: {
        default: "bg-transparent",
        icon: "[&_svg:not([class*='size-'])]:size-4",
        image:
          "size-10 overflow-hidden rounded-sm group-data-[size=sm]/item:size-8 group-data-[size=xs]/item:size-6 [&_img]:size-full [&_img]:object-cover"
      }
    },
    defaultVariants: {
      variant: "default"
    }
  }
);

function ItemMedia({
  className,
  variant = "default",
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> &
  VariantProps<typeof itemMediaVariants> & { ref?: React.Ref<React.ComponentRef<"div">> }) {
  return (
    <div
      ref={ref}
      data-slot="item-media"
      data-variant={variant}
      className={cn(itemMediaVariants({ variant, className }))}
      {...props}
    />
  );
}
ItemMedia.displayName = "ItemMedia";

function ItemContent({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="item-content"
      className={cn(
        "flex flex-1 flex-col gap-1 group-data-[size=xs]/item:gap-0 [&+[data-slot=item-content]]:flex-none",
        className
      )}
      {...props}
    />
  );
}
ItemContent.displayName = "ItemContent";

function ItemTitle({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="item-title"
      className={cn(
        itemStyles.title,
        "line-clamp-1 flex w-fit items-center gap-2 underline-offset-4",
        className
      )}
      {...props}
    />
  );
}
ItemTitle.displayName = "ItemTitle";

function ItemDescription({ className, ref, ...props }: React.ComponentProps<"p">) {
  return (
    <p
      ref={ref}
      data-slot="item-description"
      className={cn(
        itemStyles.partDescription,
        "text-muted-foreground [&>a:hover]:text-primary line-clamp-2 text-left [&>a]:underline [&>a]:underline-offset-4",
        className
      )}
      {...props}
    />
  );
}
ItemDescription.displayName = "ItemDescription";

function ItemActions({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="item-actions"
      className={cn("flex items-center gap-2", className)}
      {...props}
    />
  );
}
ItemActions.displayName = "ItemActions";

function ItemHeader({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="item-header"
      className={cn("flex basis-full items-center justify-between gap-2", className)}
      {...props}
    />
  );
}
ItemHeader.displayName = "ItemHeader";

function ItemFooter({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="item-footer"
      className={cn("flex basis-full items-center justify-between gap-2", className)}
      {...props}
    />
  );
}
ItemFooter.displayName = "ItemFooter";

export {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemFooter,
  ItemGroup,
  ItemHeader,
  ItemMedia,
  ItemSeparator,
  ItemTitle
};

export function Media({
  icon,
  size = "md",
  tone,
  children,
  className,
  style,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"span"> & {
  icon?: IconSource;
  size?: "sm" | "md" | number;
  tone?: "ok" | "warn" | "bad" | "info";
} & { ref?: React.Ref<HTMLSpanElement> }) {
  return (
    <span
      ref={ref}
      data-slot="media"
      data-size={typeof size === "number" ? undefined : size}
      data-tone={tone}
      className={cn(
        helperStyles.media,
        itemStyles.media,
        size === "sm" && helperStyles.mediaSmall,
        className
      )}
      style={{ ...(typeof size === "number" ? { width: size, height: size } : {}), ...style }}
      {...props}
    >
      {icon ? (
        <Icon
          icon={icon}
          size={size === "sm" || (typeof size === "number" && size <= 28) ? 14 : 18}
        />
      ) : (
        children
      )}
    </span>
  );
}
Media.displayName = "Media";
export function Tile({
  selected,
  title,
  description,
  media,
  children,
  className,
  type = "button",
  ref,
  ...props
}: Omit<React.ComponentPropsWithoutRef<"button">, "title"> & {
  selected?: boolean;
  title?: React.ReactNode;
  description?: React.ReactNode;
  media?: React.ReactNode;
} & { ref?: React.Ref<HTMLButtonElement> }) {
  const inFrame = useInFrame("Tile");
  return (
    <button
      ref={ref}
      type={type}
      data-slot="tile"
      data-in-frame={inFrame || undefined}
      aria-pressed={selected}
      className={cn(helperStyles.tile, className)}
      {...props}
    >
      {media && <span className={itemStyles.lead}>{media}</span>}
      <span className={helperStyles.tileBody}>
        {title !== undefined ? (
          <>
            <span
              className={itemStyles.tileTitle}
              title={typeof title === "string" ? title : undefined}
            >
              {title}
            </span>
            {description && (
              <span className={cn(itemStyles.description, itemStyles.tileDescription)}>
                {description}
              </span>
            )}
            {children}
          </>
        ) : (
          children
        )}
      </span>
      <Icon name={selected ? "check" : "chev-right"} />
    </button>
  );
}
Tile.displayName = "Tile";

.field {
  --cipher-field-height: var(--cipher-size-control-sm);
  --cipher-field-inline: var(--cipher-space-control-inline-sm);
  --cipher-field-nested: var(--cipher-size-nested-sm);
  box-sizing: border-box;
  min-height: var(--cipher-field-height);
  padding-block: calc(
    (var(--cipher-field-height) - var(--cipher-type-body-line-height)) / 2 - var(--cipher-size-control-border)
  );
  padding-inline: var(--cipher-field-inline);
  border: var(--cipher-size-control-border) solid var(--cipher-control);
  border-radius: 0;
  background-color: var(--cipher-control-surface);
  color: var(--cipher-ink);
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
  outline: none;
  transition-property: border-color, box-shadow, background-color;
  transition-duration: var(--cipher-duration-fast);
  transition-timing-function: var(--cipher-ease-fade);
}
.field[data-size="xs"] {
  --cipher-field-height: var(--cipher-size-control-xs);
  --cipher-field-inline: var(--cipher-space-6);
  --cipher-field-nested: calc(
    var(--cipher-size-control-xs) - 2 *
      (var(--cipher-space-control-slot-inset) + var(--cipher-size-control-border))
  );
  padding-block: calc(
    (var(--cipher-field-height) - var(--cipher-type-caption-line-height)) / 2 -
      var(--cipher-size-control-border)
  );
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
}
.field[data-size="xs"]:is(.fieldBox, .inputGroup) {
  padding-block: 0;
}
.field[data-size="xs"] .leading > svg {
  width: var(--cipher-size-icon-xs);
  height: var(--cipher-size-icon-xs);
}
.field[data-size="md"] {
  --cipher-field-height: var(--cipher-size-control-md);
  --cipher-field-inline: var(--cipher-space-control-inline-md);
  --cipher-field-nested: var(--cipher-size-nested-md);
}
.field[data-size="lg"] {
  --cipher-field-height: var(--cipher-size-control-lg);
  --cipher-field-inline: var(--cipher-space-control-inline);
  --cipher-field-nested: var(--cipher-size-nested-lg);
}
.field[data-width] {
  flex-shrink: 0;
  max-width: 100%;
}
.field[data-width="xs"] {
  width: var(--cipher-size-field-xs);
}
.field[data-width="sm"] {
  width: var(--cipher-size-field-sm);
}
.field[data-width="md"] {
  width: var(--cipher-size-field-md);
}
.field::placeholder,
.field ::placeholder {
  color: var(--cipher-muted);
}
@media (hover: hover) {
  .field:hover:not(:disabled, [aria-disabled="true"]) {
    background-color: var(--cipher-control-surface-hover);
  }
}
.field:is(:focus-visible, [aria-expanded="true"]),
.field[data-field-box][data-control-focus] {
  border-color: var(--cipher-ink);
  box-shadow: 0 0 0 var(--cipher-size-focus-glow) var(--cipher-focus-ring);
}
.field:is([aria-invalid="true"], [data-invalid]),
.field[data-field-box][data-control-invalid] {
  border-color: var(--cipher-control-invalid-border);
}
.field:is([aria-invalid="true"], [data-invalid]):is(:focus-visible, [aria-expanded="true"]),
.field:is([aria-invalid="true"], [data-invalid])[data-field-box][data-control-input-focus],
.field[data-field-box][data-control-invalid][data-control-invalid-focus] {
  border-color: var(--cipher-bad);
  box-shadow: 0 0 0 var(--cipher-size-focus-glow) var(--cipher-focus-ring-bad);
}
.field:is(:disabled, [aria-disabled="true"]),
.field[data-field-box][data-control-disabled] {
  cursor: not-allowed;
  opacity: 0.5;
}
.field:is([readonly], [data-field-box][data-control-readonly]) {
  background-color: var(--cipher-paper);
}
.fieldBox {
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  gap: var(--cipher-space-control-gap);
  padding-block: 0;
  cursor: text;
}
.fieldBox[data-trailing] {
  --cipher-kbd-host-block: calc(var(--cipher-field-height) - 2 * var(--cipher-size-control-border));
  --cipher-kbd-host-end: var(--cipher-space-control-slot-inset);
  padding-inline-end: var(--cipher-space-control-slot-inset);
}
.bare {
  flex: 1 1 auto;
  align-self: stretch;
  min-width: 0;
  min-height: calc(var(--cipher-field-height) - 2 * var(--cipher-size-control-border));
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  outline: none;
}
input:is(.field, .bare)[type="number"] {
  appearance: textfield;
  -moz-appearance: textfield;
}
input:is(.field, .bare)[type="number"]::-webkit-inner-spin-button,
input:is(.field, .bare)[type="number"]::-webkit-outer-spin-button {
  margin: 0;
  appearance: none;
  -webkit-appearance: none;
}
.bare:disabled {
  cursor: not-allowed;
}
.mono {
  font-family: var(--cipher-font-mono, monospace);
}
.leading,
.chevron {
  display: inline-flex;
  flex: none;
  color: var(--cipher-muted);
  pointer-events: none;
}
.chevron {
  width: var(--cipher-size-icon);
  height: var(--cipher-size-icon);
}
.trigger {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: var(--cipher-space-control-gap);
  text-align: start;
  white-space: nowrap;
}
@media (hover: hover) {
  .triggerHover:hover:not(:disabled, [aria-disabled="true"]) {
    background-color: var(--cipher-action-outline-hover);
  }
}
.triggerHover[aria-expanded="true"] {
  background-color: var(--cipher-action-outline-hover);
}
.trigger > :first-child {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.trigger > .leading {
  flex: none;
}
.trigger > .leading + * {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.trigger [data-placeholder],
.trigger[data-placeholder] > :first-child,
.trigger[data-placeholder] > .leading + * {
  color: var(--cipher-muted);
}
.textarea {
  min-height: calc(2 * var(--cipher-space-32));
  field-sizing: content;
  resize: vertical;
}
/* field-sizing: content ignores the rows attribute, so rows becomes the starting height: that many lines plus the field's padding and border, and content still grows it. */
.textarea[data-rows] {
  min-height: calc(
    var(--cipher-textarea-rows) * 1lh + var(--cipher-field-height) - var(--cipher-type-body-line-height)
  );
}
.textarea[data-mono] {
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
  tab-size: 2;
}
.searchRow {
  display: flex;
  min-height: var(--cipher-size-control-lg);
  align-items: center;
  gap: var(--cipher-space-8);
  padding-inline: calc(var(--cipher-space-menu-inset) + var(--cipher-space-8));
  /* lint-css-allow: single-row: the one search field above a menu's options */
  border-bottom: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  color: var(--cipher-muted);
  cursor: text;
}
.searchRow:focus-within {
  color: var(--cipher-ink);
}
.searchRow > svg {
  flex: none;
  pointer-events: none;
}
.searchRow > input {
  flex: 1 1 auto;
  align-self: stretch;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--cipher-ink);
  caret-color: var(--cipher-ink);
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
  outline: none;
}
