  background: var(--cipher-warn-bg);
  border-color: var(--cipher-warn-line);
  color: var(--cipher-warn);
}
.alert[data-tone="bad"] {
  background: var(--cipher-bad-bg);
  border-color: var(--cipher-bad-line);
  color: var(--cipher-bad);
}
.alertActions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--cipher-space-8);
  padding-top: var(--cipher-space-actions-gap);
}
.toastStack {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-8);
  width: max-content;
  max-width: min(var(--cipher-size-toast), 100%);
}
.toastStack.toastFixed {
  max-width: min(var(--cipher-size-toast), calc(100vw - 2 * var(--cipher-space-16)));
}
.toast {
  border-radius: 0;
  display: flex;
  align-items: flex-start;
  gap: var(--cipher-space-8);
  border: 1px solid var(--cipher-line-soft, var(--border));
  background: var(--cipher-toast-bg, var(--popover));
  color: var(--cipher-ink, var(--foreground));
  box-shadow: var(--cipher-shadow-pop, 0 4px 16px rgb(0 0 0 / 0.12));
  padding: var(--cipher-space-12);
  --cipher-toast-line: var(--cipher-type-row-title-line-height);
}
.toast > svg {
  flex: none;
  height: var(--cipher-toast-line);
}
.toastBody {
  min-width: 0;
  flex: 1 1 auto;
}
.toastTitle,
.toastDescription {
  overflow-wrap: anywhere;
}
.toast > button {
  flex: none;
  margin-block: calc((var(--cipher-toast-line) - var(--cipher-action-height)) / 2);
}
.toastActions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--cipher-space-4);
  margin-top: var(--cipher-space-8);
  margin-inline-start: calc(-1 * var(--cipher-space-control-inline-sm));
  contain: inline-size;
}
.toastActions > button {
  white-space: normal;
  max-width: 100%;
}
.avatarShape {
  border-radius: 0;
}
.avatarShape::after {
  content: "";
  position: absolute;
  inset: 0;
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  mix-blend-mode: var(--cipher-avatar-blend);
  pointer-events: none;
}
.avatarShape::after,
.avatarShape > [data-slot="avatar-fallback"],
.avatarShape > [data-slot="avatar-image"] {
  border-radius: inherit;
}
.avatarShape > [data-slot="avatar-fallback"] {
  font-size: inherit;
}
.avatarRing {
  box-shadow: 0 0 0 var(--cipher-size-focus-ring) var(--cipher-surface);
}
.avatarGroup {
  display: flex;
}
.avatarGroup > [data-slot="avatar"] + [data-slot="avatar"],
.avatarGroup > * + [data-slot="avatar-group-count"] {
  margin-inline-start: calc(-1 * var(--cipher-space-4));
}
.avatarCount {
  border-radius: 0;
  background: var(--cipher-tint);
  color: var(--cipher-muted);
  box-shadow: 0 0 0 var(--cipher-size-focus-ring) var(--cipher-surface);
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  font-weight: var(--cipher-type-caption-font-weight);
}
.avatarStatus {
  position: absolute;
  z-index: 1;
  inset-inline-end: calc(-1 * var(--cipher-space-2));
  bottom: calc(-1 * var(--cipher-space-2));
  width: var(--cipher-space-8);
  height: var(--cipher-space-8);
  box-shadow: 0 0 0 var(--cipher-size-focus-ring) var(--cipher-surface);
  background: var(--cipher-faint);
  border-radius: 0;
}

.fieldLegend {
  font-family: var(--cipher-type-title-sm-font-family);
  font-size: var(--cipher-type-title-sm-font-size);
  line-height: var(--cipher-type-title-sm-line-height);
  font-weight: var(--cipher-type-title-sm-font-weight);
  letter-spacing: var(--cipher-type-title-sm-letter-spacing);
  margin-bottom: var(--cipher-space-field-label);
}
.fieldLegend[data-variant="label"] {
  font-family: var(--cipher-type-field-label-font-family);
  font-size: var(--cipher-type-field-label-font-size);
  line-height: var(--cipher-type-field-label-line-height);
  font-weight: var(--cipher-type-field-label-font-weight);
  letter-spacing: var(--cipher-type-field-label-letter-spacing);
}
.alertTitle {
  grid-column: 1;
  grid-row: 1;
  min-width: 0;
  font-family: var(--cipher-type-row-title-font-family);
  font-size: var(--cipher-type-row-title-font-size);
  line-height: var(--cipher-type-row-title-line-height);
  font-weight: var(--cipher-type-row-title-font-weight);
  letter-spacing: var(--cipher-type-row-title-letter-spacing);
}
.alertDescription {
  grid-column: 1;
  min-width: 0;
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}

:is(.fieldDescription, .alertDescription) a:not([data-slot]) {
  color: var(--cipher-link);
  text-decoration-line: none;
  text-decoration-thickness: var(--cipher-size-control-border);
  text-underline-offset: var(--cipher-space-3);
}
:is(.fieldDescription, .alertDescription) a:not([data-slot]):focus-visible {
  text-decoration-line: underline;
}
@media (hover: hover) {
  :is(.fieldDescription, .alertDescription) a:not([data-slot]):hover {
    color: var(--cipher-text2);
    text-decoration-line: underline;
    text-decoration-thickness: var(--cipher-space-2);
  }
}

.alert {
  position: relative;
  display: grid;
  width: 100%;
  grid-template-columns: minmax(0, 1fr);
  border: 1px solid var(--cipher-line-soft);
  border-radius: 0;
  padding: var(--cipher-space-12);
  gap: var(--cipher-space-4) var(--cipher-space-8);
  overflow-wrap: anywhere;
  text-align: start;
}
.alert[data-has-icon] {
  grid-template-columns: auto minmax(0, 1fr);
}
.alert > svg {
  grid-column: 1;
  grid-row: 1 / span 2;
  align-self: start;
  transform: translateY(var(--cipher-space-2));
  color: currentColor;
}
.alert[data-has-icon] > :is(.alertTitle, .alertDescription) {
  grid-column: 2;
}
.alert[data-has-title] > .alertDescription {
  grid-row: 2;
}
.alert[data-has-action] {
  grid-template-columns: minmax(0, 1fr) auto;
  padding-inline-end: var(--cipher-space-12);
}
.alert[data-has-icon][data-has-action] {
  grid-template-columns: auto minmax(0, 1fr) auto;
}
.alertAction {
  position: static;
  grid-column: -2 / -1;
  grid-row: 1 / span 2;
  align-self: start;
}

.fieldTitle {
  font-family: var(--cipher-type-field-label-font-family);
  font-size: var(--cipher-type-field-label-font-size);
  line-height: var(--cipher-type-field-label-line-height);
  font-weight: var(--cipher-type-field-label-font-weight);
  letter-spacing: var(--cipher-type-field-label-letter-spacing);
}
.fieldGroup {
  gap: var(--cipher-space-field-group);
}
.field {
  gap: var(--cipher-space-field-label);
}
.field:not([data-orientation="horizontal"]) {
  max-width: var(--cipher-size-measure-field);
}
.field[data-width="wide"]:not([data-orientation="horizontal"]) {
  max-width: var(--cipher-size-measure-field-wide);
}
.field[data-orientation="horizontal"] {
  gap: var(--cipher-space-12);
}

.layout {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--cipher-space-12);
  width: 100%;
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
}
.layout[data-size="sm"] {
  align-items: center;
  flex-wrap: nowrap;
  gap: var(--cipher-space-8);
}
.lead {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
.main {
  display: flex;
  flex: 1 1 var(--cipher-size-text-min);
  min-width: min(100%, var(--cipher-size-text-min));
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--cipher-space-12);
}
.copy {
  flex: 1 1 var(--cipher-size-text-min);
  min-width: min(100%, var(--cipher-size-text-min));
}
.title {
  font-family: var(--cipher-type-row-title-font-family);
  font-size: var(--cipher-type-row-title-font-size);
  line-height: var(--cipher-type-row-title-line-height);
  font-weight: var(--cipher-type-row-title-font-weight);
  letter-spacing: var(--cipher-type-row-title-letter-spacing);
  min-width: 0;
  color: var(--cipher-ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.description {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  margin-top: var(--cipher-space-4);
  color: var(--cipher-text2);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tileDescription {
  display: block;
  white-space: normal;
  overflow-wrap: anywhere;
}
.error {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  display: flex;
  align-items: flex-start;
  gap: var(--cipher-space-6);
  margin-top: var(--cipher-space-4);
  color: var(--cipher-bad);
}
.actions {
  display: flex;
  flex-shrink: 0;
  align-self: flex-start;
  min-height: calc(2 * var(--cipher-type-row-title-line-height));
  align-items: center;
  flex-wrap: wrap;
  gap: var(--cipher-space-8);
  max-width: 100%;
}
.main[data-actions-below] {
  row-gap: var(--cipher-space-actions-gap);
}
.layout[data-has-actions] {
  container: cipher-item / inline-size;
}
.layout[data-has-actions][data-variant="outline"] {
  padding: var(--cipher-space-24);
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.layout[data-has-actions] > .lead {
  align-self: flex-start;
  min-height: calc(
    var(--cipher-type-row-title-line-height) + var(--cipher-space-2) +
      var(--cipher-type-small-line-height)
  );
}
.main[data-has-actions] {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas:
    "copy"
    "actions";
  align-items: start;
  row-gap: var(--cipher-space-actions-gap);
}
.main[data-has-actions] > .copy {
  grid-area: copy;
  min-width: 0;
}
.main[data-has-actions] > .actions {
  grid-area: actions;
  justify-content: flex-start;
  min-height: 0;
}
.main[data-has-actions] .titleLine {
  flex-wrap: nowrap;
  align-items: baseline;
}
.main[data-has-actions] .titleLine > .unread {
  align-self: center;
}
.main[data-has-actions] .titleLine > .meta {
  flex: none;
}
.main[data-has-actions] .description {
  margin-top: var(--cipher-space-2);
}
.main[data-actions-icon-only]:not([data-actions-below]) {
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "copy actions";
  column-gap: var(--cipher-space-16);
}
@container cipher-item (min-width: 44rem) {
  .main[data-has-actions]:not([data-actions-below]) {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas: "copy actions";
    column-gap: var(--cipher-space-32);
  }
  .main[data-has-actions]:not([data-actions-below]) .titleLine > .meta {
    margin-inline-start: 0;
  }
  .main[data-has-actions]:not([data-actions-below]) > .actions {
    flex-wrap: nowrap;
    min-height: calc(
      var(--cipher-type-row-title-line-height) + var(--cipher-space-2) +
        var(--cipher-type-small-line-height)
    );
  }
}
.below {
  flex-basis: 100%;
}
.wrap .title,
.wrap .description {
  white-space: normal;
  overflow-wrap: anywhere;
}
.body {
  margin-top: var(--cipher-space-8);
  min-width: 0;
}
.mono {
  font-family: var(--cipher-font-mono);
}
.unread {
  flex-shrink: 0;
  width: var(--cipher-space-6);
  height: var(--cipher-space-6);
  background: var(--cipher-accent-fg);
  border-radius: 0;
}
.lead > .unread {
  position: absolute;
  top: calc(-1 * var(--cipher-space-2));
  right: calc(-1 * var(--cipher-space-2));
  box-shadow: 0 0 0 var(--cipher-space-2) var(--cipher-surface);
}
.layout[data-unread] .title {
  font-weight: 600;
}
.layout[data-size="sm"] .description {
  display: none;
}
.layout[data-size="sm"] .main,
.layout[data-size="sm"] .copy {
  min-width: 0;
  flex-wrap: nowrap;
}
.media[data-tone="ok"] {
  background: var(--cipher-ok-wash);
  border-color: var(--cipher-ok-line);
  color: var(--cipher-ok);
}
.media[data-tone="warn"] {
  background: var(--cipher-warn-wash);
  border-color: var(--cipher-warn-line);
  color: var(--cipher-warn);
}
.media[data-tone="bad"] {
  background: var(--cipher-bad-wash);
  border-color: var(--cipher-bad-line);
  color: var(--cipher-bad);
}
.media[data-tone="info"] {
  background: var(--cipher-info-wash);
  border-color: var(--cipher-info-line);
  color: var(--cipher-info);
}
.tileTitle {
  font-family: var(--cipher-type-row-title-font-family);
  font-size: var(--cipher-type-row-title-font-size);
  line-height: var(--cipher-type-row-title-line-height);
  font-weight: var(--cipher-type-row-title-font-weight);
  letter-spacing: var(--cipher-type-row-title-letter-spacing);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  overflow-wrap: anywhere;
  color: var(--cipher-ink);
}

.titleLine {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  min-width: 0;
  flex-wrap: wrap;
}
.titleLine > .title {
  flex: 0 1 auto;
  min-width: 0;
}
.titleLine > .clamp {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  white-space: normal;
  overflow-wrap: anywhere;
}
.meta {
  font-family: var(--cipher-type-mono-sm-font-family);
  font-size: var(--cipher-type-mono-sm-font-size);
  line-height: var(--cipher-type-mono-sm-line-height);
  font-weight: var(--cipher-type-mono-sm-font-weight);
  letter-spacing: var(--cipher-type-mono-sm-letter-spacing);
  margin-inline-start: auto;
  flex-shrink: 0;
  color: var(--cipher-muted);
  max-width: 100%;
  overflow-wrap: anywhere;
}

.partDescription {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  overflow-wrap: anywhere;
}
.layout[data-size="sm"] .actions {
  align-self: center;
  min-height: 0;
}
